#include <iostream>
#include <string>
#include <utility>

template <typename T>
class Caja {
public:
    explicit Caja(T valor) : valor_(std::move(valor)) {}
    const T& valor() const { return valor_; }
    void guardar(T nuevo) { valor_ = std::move(nuevo); }
private:
    T valor_;
};

int main() {
    Caja<int> entero(42);
    Caja<std::string> texto("modelo");

    entero.guardar(7);
    std::cout << entero.valor() << ' ' << texto.valor() << '\n'; // 7 modelo

    Caja deducida(3.5);                 // C++17: deduce Caja<double>
    std::cout << deducida.valor() << '\n';
    return 0;
}

#include <iostream>

template <typename... Ts>
auto cantidad(const Ts&... valores) {
    return sizeof...(valores);
}

template <typename T>
T suma(T valor) {
    return valor;
}

template <typename T, typename... Resto>
T suma(T primero, Resto... resto) {
    return primero + suma(resto...);
}

int main() {
    std::cout << cantidad(1, 2.5, "tres") << '\n'; // 3
    std::cout << suma(1, 2, 3, 4) << '\n';         // 10
    return 0;
}

