#include <iostream>
#include <vector>

template <typename T>
T suma_vector(const std::vector<T>& datos) {
    T total{};
    for (const T& valor : datos) {
        total += valor;
    }
    return total;
}

int main() {
    std::vector<int> enteros{1, 2, 3};
    std::vector<double> reales{1.5, 2.0, 2.5};

    std::cout << suma_vector(enteros) << '\n'; // 6
    std::cout << suma_vector(reales) << '\n';  // 6
    return 0;
}

#include <concepts>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

template <typename T>
concept Ordenable = requires(const T& a, const T& b) {
    { a < b } -> std::convertible_to<bool>;
};

template <Ordenable T>
T minimo(const std::vector<T>& datos) {
    if (datos.empty()) {
        throw std::invalid_argument("vector vacio");
    }
    T mejor = datos.front();
    for (const T& valor : datos) {
        if (valor < mejor) {
            mejor = valor;
        }
    }
    return mejor;
}

int main() {
    std::vector<int> enteros{5, 2, 9};
    std::vector<std::string> nombres{"ana", "bea", "zoe"};

    std::cout << minimo(enteros) << '\n';  // 2
    std::cout << minimo(nombres) << '\n';  // ana
    return 0;
}

